mapper.update:
UPDATE cart_items
SET quantity = #{quantity}
WHERE id = #{id}

mapper.select:
SELECT ci.id, ci.product_id, p.name, p.main_image_url, p.price, ci.quantity, (p.price * ci.quantity) AS sub_total FROM cart_items ci JOIN product p ON p.product_id = ci.product_id AND p.is_deleted = 0 WHERE ci.cart_id = #{cartId}
AND p.name ILIKE CONCAT('%', #{q}, '%')
ORDER BY
p.name p.price p.updated_at p.created_at
ASC DESC
LIMIT #{__limit} OFFSET #{__offset}
